mapper.select:
SELECT tpl.TPL_SEQ tplSeq , tpl.TPL_NAME tplName , FN_GET_COMM_CODE_DESC('TPL_PHASE', tpl.TPL_PHASE) tplPhase FROM TB_EXER_TPL tpl INNER JOIN TB_EXER exer ON tpl.TPL_SEQ = exer.TPL_SEQ INNER JOIN TB_EXER_ATTR attr ON exer.TPL_ATTR_SEQ = attr.TPL_ATTR_SEQ WHERE tpl.USE_YN = 'Y' AND tpl.DEL_YN = 'N'
AND attr.TPL_TYPE_CODE = #{tplType}
AND ( MATCH(tpl.TPL_NAME) AGAINST(CONCAT('+', #{tplName}, '*') IN BOOLEAN MODE) OR tpl.TPL_NAME LIKE CONCAT('%', #{tplName}, '%') )
AND tpl.TPL_PHASE IN
#{phase}
AND attr.TPL_CATEGORY_CODE IN
#{cat}
GROUP BY tpl.TPL_SEQ ORDER BY tpl.SORT_ORDER

mapper.insert:
INSERT INTO TB_EXER_TPL (
    TPL_NAME
    , TPL_PHASE
    , SORT_ORDER
    , USE_YN
    , DEL_YN
    , INS_USER_ID
    , INS_IP
    , INS_DT
) VALUES (
    #{tplName}
    , #{tplPhase}
    , (SELECT IFNULL(MAX(T.SORT_ORDER), 0) + 1 FROM TB_EXER_TPL T)
    , 'Y'
    , 'N'
    , #{insUserId}
    , #{insIp}
    , NOW()
)

INSERT INTO TB_EXER_ATTR (
    TPL_TYPE_CODE
    , TPL_EXER_NAME
    , TPL_CATEGORY_CODE
    , TPL_KIND_CODE
    , TPL_NOTE
    , TPL_SORT_ORDER
    , USE_YN
    , DEL_YN
    , INS_DT
) VALUES (
    #{tplTypeCode}
    , #{tplExerName}
    , #{tplCategoryCode}
    , #{tplKindCode}
    , #{tplNote}
    , #{tplSortOrder}
    , 'Y'
    , 'N'
    , NOW()
)

mapper.update:
UPDATE TB_EXER_ATTR
SET TPL_EXER_NAME = #{tplExerName}
    , TPL_CATEGORY_CODE = #{tplCategoryCode}
    , TPL_KIND_CODE = #{tplKindCode}
    , TPL_NOTE = #{tplNote}
    , TPL_SORT_ORDER = #{tplSortOrder}
    , UPD_DT = NOW()
WHERE TPL_ATTR_SEQ = #{tplAttrSeq}

UPDATE TB_EXER_ATTR
SET DEL_YN = 'Y', UPD_DT = NOW()
WHERE TPL_ATTR_SEQ = #{_parameter}

mapper.insert:
INSERT INTO TB_EXER (
    TPL_SEQ
    , TPL_ATTR_SEQ
) VALUES (
    #{tplSeq}
    , #{tplAttrSeq}
)

mapper.update:
UPDATE TB_EXER_ATTR
SET TPL_SORT_ORDER = CASE

        WHEN TPL_ATTR_SEQ = #{item.tplAttrSeq} THEN #{item.tplSortOrder}

END,
UPD_DT = NOW(),
UPD_IP = #{list[0].updIp},
UPD_USER_ID = #{list[0].updUserId}
WHERE TPL_ATTR_SEQ IN

    #{item.tplAttrSeq}

UPDATE TB_EXER_TPL
SET TPL_NAME = #{tplName}
    , TPL_PHASE = #{tplPhase}
    , UPD_USER_ID = #{updUserId}
    , UPD_IP = #{updIp}
    , UPD_DT = NOW()
WHERE TPL_SEQ = #{tplSeq}

UPDATE TB_EXER_TPL
SET DEL_YN = 'Y'
    , UPD_USER_ID = #{updUserId}
    , UPD_IP = #{updIp}
    , UPD_DT = NOW()
WHERE TPL_SEQ = #{tplSeq}

UPDATE TB_EXER_ATTR attr, TB_EXER exer
SET attr.DEL_YN = 'Y'
    , attr.UPD_USER_ID = #{updUserId}
    , attr.UPD_IP = #{updIp}
    , attr.UPD_DT = NOW()
WHERE attr.TPL_ATTR_SEQ = exer.TPL_ATTR_SEQ
AND exer.TPL_SEQ = #{tplSeq}
